cases.setup:
git init -q . && printf 'public class Calc {
    public static int add(int a, int b) {
        return a - b;
    }
}
' > Calc.java && git add . && git -c user.email=e@e -c user.name=eval commit -qm 'feat: calc'

git init -q . && printf 'public class Clamp {
    public static int clamp(int v, int lo, int hi) {
        return Math.max(lo, Math.min(v, hi));
    }
}
' > Clamp.java && git add . && git -c user.email=e@e -c user.name=eval commit -qm 'feat: clamp'
